-- purpose: 令和7年第1回(3月)定例会のデータを会議録から新規投入する
-- affected: assemblies, agenda_items, general_questions, question_topics, council_members
-- sources:
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070304.pdf (3/4 開会・施政方針・一般質問)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070305.pdf (3/5 一般質問)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070307.pdf (3/7 議案審議: 同意1号・議案6〜23号)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070310.pdf (3/10 議案24〜30号・予算特別委員会設置)
--   https://www.town.hirokawa.fukuoka.jp/material/files/group/37/070319.pdf (3/19 委員長報告・採決・閉会)
-- notes: total_agenda_itemsは開会時の町長挨拶で示された「人事案件1件、条例の制定1件、
--        条例の一部改正10件、福岡県市町村職員退職手当組合規約の変更1件、令和6年度補正
--        予算6件、令和7年度当初予算6件の計25件」に基づく(同意第1号+議案第6号〜29号)。
--        議案第30号(国保税条例一部改正)・議案第31号(R6一般会計補正予算第8号)・議案第
--        32号(R6後期高齢者医療特別会計補正予算第4号)は、いずれも開会時の「計25件」に
--        含まれない追加提出案件(3/10・3/19の各本会議で新たに上程)のため、r7-3・r7-4・
--        r7-2の発委・発議と同様の扱いで26〜28件目としてagenda_itemsに追加登録する。
--        議案第24号(一般会計予算)は12人の委員による一般会計予算審査特別委員会に付託さ
--        れ、3/12〜14の分科会審査・3/18の委員会採決を経て3/19の本会議で賛成多数(起立
--        多数、反対討論:江藤美代子・竹下英治、賛成討論:丸山幸弘)で可決、附帯決議9項目
--        が付された。議案第25号(国保特別会計予算)も厚生文教常任委員会付託・起立多数
--        可決(反対討論:江藤美代子、賛成討論:丸山幸弘、附帯決議3項目)。議案第26〜29号
--        (後期高齢者医療・防災ダム・水道・下水道の各特別/企業会計予算)は所管の厚生文
--        教常任委員会または総務産業常任委員会に付託され、いずれも全会一致で可決(27〜
--        29号に附帯決議あり)。当初予算関連の議案第24〜29号は、令和8年第1回定例会の
--        移行時(20260815120000)と同様、proposal_reasonは本文が長大なためNULLのまま
--        としている。
--        agenda_items.statusはCHECK制約(可決・否決・継続審査・撤回・未審議のみ)に対応
--        するため、報告→可決の変換ルールを適用(本定例会に該当なし)。議案第6号(刑法等
--        改正に伴う関係条例整理条例、拘禁刑への単一化)は起立採決で起立多数により可決
--        (反対討論:江藤美代子[国連被拘禁者処遇最低基準規則を根拠に人権保障の観点から
--        反対]、賛成討論:栗原福裕・竹下英治)。議案第30号(国保税条例一部改正、資産割
--        廃止の最終回)も起立採決で起立多数可決(反対討論:江藤美代子、賛成討論:丸山幸弘)。
--        その他の議案・同意は全て全会一致(異議なし)で可決。
--        council_membersは一般質問した10名のうち、野田成幸議員(12番)のみ既存レコード
--        で解決できず新規作成する(seat_numberは会議録冒頭の応招議員一覧「12番　野田成
--        幸」より12と確認)。他の9名(梶原一美・竹下英治・江藤美代子・山下茂・水落龍彦・
--        下田めぐみ・池尻浩一・藤島玄稔・栗原福裕)は全員既存レコードで解決できる。

do $$
declare
  v_assembly_id uuid := 'b54c4cc2-2612-46f8-8a8e-01e57a5f6579';
begin

  -- 冪等ガード: 既に投入済みなら何もしない
  if exists (
    select 1 from public.assemblies
    where fiscal_year = 2025
      and session_type = '定例会'
      and session_number = 1
  ) then
    raise notice '既に投入済みのためスキップします';
    return;
  end if;

  insert into public.assemblies
    (id, name, session_type, session_number, fiscal_year, start_date, end_date, total_agenda_items)
  values
    (v_assembly_id, '令和7年第1回定例会', '定例会', 1, 2025, '2025-03-04', '2025-03-19', 25);

  -- council_members: 会議録の応招議員一覧に基づき、既存に存在しない議員のみ新規作成
  insert into public.council_members (id, name, seat_number, role)
  select '5eb5e9e6-0a81-44b1-ad40-2b74b2d239fb', '野田成幸', 12, '一般'
  where not exists (select 1 from public.council_members where name = '野田成幸');

  -- agenda_items
  insert into public.agenda_items
    (id, assembly_id, item_number, title, category, proposal_reason, status, decided_on, display_order)
  values
    ('42bda399-b749-454b-aaae-e6c461cc18e1', v_assembly_id, '同意第1号', '広川町副町長の選任に対する同意について', '人事', '副町長に川畑研介氏(平成5年8月生、厚生労働省医政局総務課職員)を令和7年7月1日から選任するもので、内閣府の地方創生人材支援制度を活用したマッチングによるもの。下田めぐみ・江藤美代子・竹下英治各議員から政策監との役割分担や人選経緯について質疑があったが、討論省略の上、全会一致で同意された。', '可決', '2025-03-07', 1),
    ('aa9ef15a-5fcd-4f35-b8a0-38ee8379d36c', v_assembly_id, '議案第6号', '刑法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例について', '条例の改正', '刑法等の一部を改正する法律により「懲役」及び「禁錮」が「拘禁刑」に一本化されること(施行日令和7年6月1日)に伴い、広川町議会の個人情報保護条例など関係6条例の文言を整理するもの。江藤美代子議員は国連被拘禁者処遇最低基準規則を引用し人権保障の観点から反対討論、栗原福裕・竹下英治両議員は国の制度改正への対応として妥当と賛成討論を行い、起立採決の結果、起立多数で可決された。', '可決', '2025-03-07', 2),
    ('855e96c9-91ba-4baf-8fd8-67a6e2e10028', v_assembly_id, '議案第7号', '広川町特別職の指定等に関する条例を廃止する条例の制定について', '条例の制定', '地方公務員法第3条第3項第4号の政策監の職を令和7年6月30日をもって廃止するため、根拠条例を廃止する条例を制定するもの。竹下英治・江藤美代子両議員から副町長選任との関係や廃止の必要性について質疑があり、町長は町長の恣意的運用を防ぐため必要が生じた都度条例を制定・廃止する方針であると説明した。', '可決', '2025-03-07', 3),
    ('263944b2-fd43-44ae-9c44-889faedd8426', v_assembly_id, '議案第8号', '広川町職員の勤務時間及び休暇等に関する条例及び広川町職員の育児休業等に関する条例の一部改正について', '条例の改正', '育児休業、介護休業等育児又は家族介護を行う労働者の福祉に関する法律等の一部改正(令和7年4月1日施行)に伴い、深夜勤務・時間外勤務の制限対象となる育児の年齢要件を3歳未満から小学校就学前までに拡大するほか、配偶者等の介護に関する意向確認等の規定を新設するもの。', '可決', '2025-03-07', 4),
    ('316434b6-769e-4d95-8c20-0e7881a43231', v_assembly_id, '議案第9号', '広川町特別職の職員の給与及び旅費に関する条例の一部改正について', '条例の改正', '常勤の特別職である町長、副町長及び教育長に通勤手当を支給可能とするため改正するもの。副町長選任や教育長の町外通勤を契機とした見直しで、下田めぐみ議員の質疑に対し総務課長は近距離であれば支給されない旨を説明した。', '可決', '2025-03-07', 5),
    ('6ff141a0-b218-44ba-8e44-4cc64c5ead58', v_assembly_id, '議案第10号', '広川町職員の給与に関する条例の一部改正について', '条例の改正', '令和6年人事院勧告に準じ、55歳超職員の標準昇給をゼロとする改正、配偶者に係る扶養手当の廃止(経過措置あり)、子に係る扶養手当の増額、管理職員特別勤務手当の支給要件見直し等を行うもの。栗原福裕議員から7級制導入や管理職の待遇改善について質疑があった。', '可決', '2025-03-07', 6),
    ('9ddb53d0-c970-4573-ae60-ba8297c9b31d', v_assembly_id, '議案第11号', '広川町会計年度任用職員の給与及び費用弁償に関する条例の一部改正について', '条例の改正', '会計年度任用職員の期末手当支給割合を年間0.05月分増額するほか、年度途中の給与改定を可能にする改正等を行うもの。', '可決', '2025-03-07', 7),
    ('e754d749-4288-4d80-ab0f-8a8fb7e9ffed', v_assembly_id, '議案第12号', '広川町の職員等の旅費支給に関する条例の一部改正について', '条例の改正', '国家公務員等の旅費に関する法律の改正に伴い、宿泊料を定額制から地域ごとの実費支給に改めるとともに、転居費・着後滞在費・家族移転費を新設するもの。', '可決', '2025-03-07', 8),
    ('7ac1946f-e44b-4acf-9bef-6b21f108b354', v_assembly_id, '議案第13号', '広川町特定教育・保育施設及び特定地域型保育事業の運営に関する基準を定める条例及び広川町家庭的保育事業等の設備及び運営に関する基準を定める条例の一部改正について', '条例の改正', '子ども・子育て支援法施行規則等の改正に伴い、連携施設確保が困難な場合の適用除外要件の追加や連携施設に関する経過措置の適用期間延長(10年→15年)、栄養士配置要件への管理栄養士追加等を行うもの。', '可決', '2025-03-07', 9),
    ('f1d93dc5-7fea-4b00-8651-d1e308c5446a', v_assembly_id, '議案第14号', '広川町水道事業及び下水道事業の設置等に関する条例の一部改正について', '条例の改正', '寺内ダム再生事業における利水容量から治水容量への振替に伴い、福岡県南広域水道企業団の構成団体の1日最大供給水量(基本水量)が6,800立方メートルから5,500立方メートルに変更されたため改正するもの。', '可決', '2025-03-07', 10),
    ('793112ac-f637-4dcd-af72-42d58039b2ef', v_assembly_id, '議案第15号', '広川町水道布設工事監督者の配置及び資格並びに水道技術管理者の資格に関する条例の一部改正について', '条例の改正', '水道法施行令及び施行規則の一部改正により、布設工事監督者・水道技術管理者の学科要件に機械工学科・電気工学科等を追加し、実務経験年数の必要年数を短縮するもの。', '可決', '2025-03-07', 11),
    ('8f7abbda-6f16-44a6-b200-73e965326729', v_assembly_id, '議案第16号', '広川町非常勤消防団員に係る退職報償金の支給に関する条例の一部改正について', '条例の改正', '消防団員等公務災害補償等責任共済等に関する法律施行令の改正により、退職報償金の勤務年数区分に31年から35年までの区分が新たに追加されたことに伴い改正するもの。', '可決', '2025-03-07', 12),
    ('17c4bbb6-25e8-4a71-91f5-ad00a8647b55', v_assembly_id, '議案第17号', '福岡県市町村職員退職手当組合を組織する地方公共団体の数の減少及び福岡県市町村職員退職手当組合規約の変更について', '規約変更', '令和7年3月31日限りで下田川清掃施設組合が解散されることに伴い、同組合を構成団体から除く規約変更について地方自治法第290条の規定により議決を求めるもの。', '可決', '2025-03-07', 13),
    ('4d746e6d-d014-402a-8c7d-82f464b3ad6f', v_assembly_id, '議案第18号', '令和6年度広川町一般会計補正予算（第7号）について', '補正予算', '既定予算総額から歳入歳出それぞれ200,657千円を減額し、予算総額を9,568,424千円とするもの。普通交付税再算定による115,581千円の増額や各種事業費の実績見込みによる減額、16事業604,405千円の繰越明許費設定等が主な内容。', '可決', '2025-03-07', 14),
    ('8fb6cce3-364f-4df8-8ad2-8117773dae1f', v_assembly_id, '議案第19号', '令和6年度広川町国民健康保険特別会計補正予算（第3号）について', '補正予算', '既定予算総額から2,400千円を減額し、予算総額を2,439,168千円とするもの。国民健康保険税の増額や保険給付費等交付金の減額等による調整。', '可決', '2025-03-07', 15),
    ('4bf67f85-5ece-4ace-b0c0-bb3c039e1d9a', v_assembly_id, '議案第20号', '令和6年度広川町後期高齢者医療特別会計補正予算（第3号）について', '補正予算', '既定予算総額から536千円を減額し、予算総額を349,014千円とするもの。', '可決', '2025-03-07', 16),
    ('d185e836-7f12-43fa-9667-47bb505296cc', v_assembly_id, '議案第21号', '令和6年度広川防災ダム管理特別会計補正予算（第2号）について', '補正予算', '既定予算総額から300千円を減額し、予算総額を27,551千円とするもの。', '可決', '2025-03-07', 17),
    ('b0563e2e-f676-4db5-956b-069115f90e58', v_assembly_id, '議案第22号', '令和6年度広川町水道事業会計補正予算（第3号）について', '補正予算', '収益的収入を8,883千円増額、収益的支出を2,130千円・資本的収入を3,210千円それぞれ減額し、予算総額412,903千円とするもの。', '可決', '2025-03-07', 18),
    ('be9c59d4-c374-44a2-8a69-29aa3a9bd874', v_assembly_id, '議案第23号', '令和6年度広川町下水道事業会計補正予算（第3号）について', '補正予算', '収益的収入を2,074千円増額、収益的支出を12,964千円・資本的収入を10,753千円・資本的支出を4,101千円それぞれ減額し、予算総額673,556千円とするもの。', '可決', '2025-03-07', 19),
    ('d0252136-3853-4920-89e0-e7e14d063fd3', v_assembly_id, '議案第24号', '令和7年度広川町一般会計予算について', '予算', NULL, '可決', '2025-03-19', 20),
    ('dbc80b8e-89ac-40cf-a42e-10bd9947569a', v_assembly_id, '議案第25号', '令和7年度広川町国民健康保険特別会計予算について', '予算', NULL, '可決', '2025-03-19', 21),
    ('97a17e0c-5b4d-42ae-90d6-a6a5e8c7c9d1', v_assembly_id, '議案第26号', '令和7年度広川町後期高齢者医療特別会計予算について', '予算', NULL, '可決', '2025-03-19', 22),
    ('ebefb6cc-db62-4094-9c8e-9b8c2718af09', v_assembly_id, '議案第27号', '令和7年度広川防災ダム管理特別会計予算について', '予算', NULL, '可決', '2025-03-19', 23),
    ('5ce8cbd1-6c06-46e1-8a4b-adfb112a460a', v_assembly_id, '議案第28号', '令和7年度広川町水道事業会計予算について', '予算', NULL, '可決', '2025-03-19', 24),
    ('7f16d8f4-5c0a-4e37-a3e1-4944193a2585', v_assembly_id, '議案第29号', '令和7年度広川町下水道事業会計予算について', '予算', NULL, '可決', '2025-03-19', 25),
    ('c4cec272-b83b-4cba-a696-35d6990fdfb5', v_assembly_id, '議案第30号', '広川町国民健康保険税条例の一部改正について', '条例の改正', '令和3年度から5年かけて段階的に減らしてきた資産割を最終回として完全廃止し、これに伴う減収分を医療保険分・後期支援分・介護保険分それぞれの均等割・平等割額の引上げで補完するもの。江藤美代子議員は低所得世帯の負担への配慮から反対討論、丸山幸弘議員は近隣市町との均衡等を理由に賛成討論を行い、起立採決の結果、起立多数で可決された。', '可決', '2025-03-10', 26),
    ('a003b0df-ee8c-42f4-95aa-547ad67d0501', v_assembly_id, '議案第31号', '令和6年度広川町一般会計補正予算（第8号）について', '補正予算', '既定予算総額に歳入歳出それぞれ7,002千円を追加し、予算総額を9,575,426千円とするもの。後期高齢者医療特別会計への保険基盤安定繰出金に係る予算を計上。', '可決', '2025-03-19', 27),
    ('fd74a389-00d4-4a11-b139-a0c6be9fc6a4', v_assembly_id, '議案第32号', '令和6年度広川町後期高齢者医療特別会計補正予算（第4号）について', '補正予算', '既定予算総額に7,002千円を追加し、予算総額を356,016千円とするもの。一般会計からの保険基盤安定繰入金の増額に対応する後期高齢者医療広域連合納付金の増額。', '可決', '2025-03-19', 28);

  -- general_questions: council_member_idは氏名で既存レコード(野田成幸は上で新規作成)を解決する
  insert into public.general_questions (id, assembly_id, council_member_id, order_number, title)
  select 'd461a0d4-71f2-44ee-80f0-7d1e853a2367', v_assembly_id, cm.id, 1, '学校プールの検討状況、タブレット活用の状況、上広川小学校移転計画について'
