  -- question_topics: 会議録の質疑応答の内容に基づく
  insert into public.question_topics
    (id, general_question_id, topic_title, raw_excerpt, department, display_order)
  values
    ('00474548-3f21-4af6-80c2-5d57b532fb97', 'd461a0d4-71f2-44ee-80f0-7d1e853a2367', '学校プール整備・水泳授業民間委託の検討', 'プール老朽化に伴い、上広川小・下広川小は令和7年度から水泳授業の民間委託を本格実施、広川中学校も試行実施することとした。梶原議員は各校統合プールの実現可能性について代替スケジュール案を示し検討を求めたが、安全面(死亡事故事例)やカリキュラム調整の困難さから、教育委員会は各校にプールを設置しない方針を維持した。', '教育委員会事務局子ども課', 1),
    ('feba7a9f-37ce-4c04-b1a1-e6f68ea9e0e9', 'd461a0d4-71f2-44ee-80f0-7d1e853a2367', 'タブレット端末の活用状況とICT環境整備', '全児童・生徒に1人1台端末を整備済みで、Wi-Fi環境が家庭で整っている割合は町全体で97.8%。共同学習時のネットワーク遅延が課題として挙げられ、新しい共同学習ソフトの試行導入や、文科省推奨帯域(200人規模で377Mbps等)を踏まえたネットワーク更新を検討しているとの答弁があった。', '教育委員会事務局子ども課', 2),
    ('f3d5b5f1-ba2a-4d26-b25c-20765dec0bca', 'd461a0d4-71f2-44ee-80f0-7d1e853a2367', '上広川小学校移転計画の進捗', '国道3号広川八女バイパス事業のルート中心線が上広川小学校の中央部を通ることが確定しており、現在地での存続は困難との見解が建設課長より示された。町は3月中旬に地元4行政区で住民説明会を開催予定で、道路計画の詳細が固まり次第、令和7年度中に学校移転検討委員会を立ち上げる方針。', '建設課', 3),

    ('dcb823fa-454f-4f3b-a112-29045c7321b1', '1029053b-4c82-4f9a-b173-1a7e5061962d', '人権セミナーの成果と拉致問題啓発', '令和6年度の人権セミナーは参加者数・アンケート結果は良好だったが学校・行政職員以外の参加が少なく、地域巡回講座(住みよいまちづくり懇談会)の参加者数の方が上回ったと教育長が説明。竹下議員はLGBT理解増進法に伴うセミナーの令和7年度実施の是非や、人権フェスタでの北朝鮮拉致問題啓発コーナー(来場者約160名)の効果を質し、生涯学習課長は体制を整えた上での実施を検討するとした。', '教育委員会事務局生涯学習課', 1),
    ('66259ece-b1ad-4633-81b3-8190ad2a828c', '1029053b-4c82-4f9a-b173-1a7e5061962d', '学校プールの民間委託検討状況', '令和6年度に上広川小・下広川小で試行した水泳授業の民間委託は、児童・保護者・教職員アンケートでいずれも8割超が肯定的評価。これを受け令和7年度から両校で本格実施し、老朽化が進む広川中学校でも試行実施することとした。竹下議員は各校統合型プール新設の可能性を問うたが、公営プールも選択肢の一つとして積算を検討中との回答があった。', '教育委員会事務局生涯学習課', 2),
    ('88b27022-406a-472f-8dba-8c4552d3f94b', '1029053b-4c82-4f9a-b173-1a7e5061962d', 'GIGAスクール構想の進捗とタイムライン', '広川町GIGAスクール推進方針には数値目標や期限は定められておらず、概ね予定どおり進んでいるとの認識が示された。竹下議員はWi-Fi環境のない家庭への対応やタブレット持ち帰り実証実験が計画どおり進んでいない点を指摘し、明確なタイムラインの設定を求めた。', '教育委員会事務局子ども課', 3),
    ('8f586be1-4d4b-48f5-8419-7ebbc0408a6f', '1029053b-4c82-4f9a-b173-1a7e5061962d', '学校におけるLGBT教育の実施方針', '令和5年6月制定の性的指向及びジェンダーアイデンティティの多様性に関する国民の理解の増進に関する法律を踏まえ、学校では多様性を尊重する教育を推進していると教育長が説明。令和7年度にLGBT理解増進法に特化したセミナーを実施する予定はないが、教職員研修等を通じて理解を深めていく方針とした。', '教育委員会事務局生涯学習課', 4),
    ('e449a8b2-d1e0-401a-b825-6d3d1eef86a9', '1029053b-4c82-4f9a-b173-1a7e5061962d', 'Kibiru・Orige・Hodokuの評価と今後の活用方針', '令和6年度(1月末時点)の利用実績はKibiru616名、Orige延べ548名、Hodoku174名で、いずれも移住・交流人口創出等に一定の成果があったと町長は評価。Kibiru・Origeの指定管理期間満了(本年度)に伴い、新しい地方経済・生活環境創生交付金(第2世代交付金)を活用し、令和7年度からOrige・Hodokuを一体運用する新たな指定管理者を募集する方針。Kibiruは教育委員会所管として今後の活用検討・実証実験を進めるとした。', '企画課', 5),
    ('9de02f8c-9866-4327-9c3b-f08f5ff6af00', '1029053b-4c82-4f9a-b173-1a7e5061962d', '中国蘇州市との友好協定の取扱い', '中国蘇州市滄浪区との友好交流協定は合併により姑蘇区となって以降、更新されないまま実質的に交流が中断している状況。県からは協定の継続・廃止を当事者間で判断するよう指導を受けているが、町は現時点でいずれの判断もしておらず、令和7年度に中国との交流事業を実施する計画もないと企画課長が答弁した。', '企画課', 6),
    ('ad81667c-ce52-4e5a-b679-478124f44fd0', '1029053b-4c82-4f9a-b173-1a7e5061962d', 'ふるさと納税の実績と使途', 'ふるさと納税の寄付額は令和4年度134,739千円、令和5年度93,158千円、令和6年度は2月末時点で220,684千円まで増加。経費は令和6年度概算で113,420千円、広川町民が他自治体へ寄付した額は令和4年度22,213千円・令和5年度24,932千円。差引残額は基金に積立て、子育て・地域産業・文化スポーツ振興等5つの使途区分に応じて充当している。', '企画課', 7),
    ('3f155cbf-492d-44c4-8448-39f05787833a', '1029053b-4c82-4f9a-b173-1a7e5061962d', '副町長を置かないための例規整備', '副町長を置かない条例は制定せず、席を空席のまま行政運営を行ってきた。副町長の権限や委員会構成員としての規定を含む例規については、できる限り例外規定で対応する方針とし、対応できない場合は各課で個別に改正してきたと町長は説明、これまで支障は生じていないとした。竹下議員は農業委員会委員候補者選定委員会運営規程など副町長を構成員とする規則が改正されないまま残っている点を指摘した。', '総務課', 8),
    ('48beb4f7-b8da-47e4-8b54-a5b364567175', '1029053b-4c82-4f9a-b173-1a7e5061962d', '広川町農業の過去10年間の変遷', '農業就業人口は平成27年1,037人から令和2年959人へ8%減少。認定農業者数は平成27年度162人、令和6年度158人とほぼ横ばい。新規就農者数は平成27年度から令和6年度予定まで10年間で29人。町は今後も県・JA・関係団体と連携し補助事業を活用した担い手確保に取り組むと町長が答弁した。', '産業課', 9),
    ('9979a603-232c-4ca2-ab28-5fec8a68427e', '1029053b-4c82-4f9a-b173-1a7e5061962d', '農業委員会の活動状況', '農業委員会は農業委員14名・農地利用最適化推進委員13名の計27名で構成。農地の権利移動・転用許可に関する審議や、耕作放棄地・遊休農地の把握、無断転用の通報対応など農地パトロールを実施していると農業委員会事務局長が説明した。', '農業委員会事務局', 10),

    ('354f1602-6f76-4d00-84ff-6e8c8a99a8a1', '3156aae0-4fa9-40f7-900f-04f69280de01', '国保健康保険証の移行に伴う周知・資格確認書', '健康保険証の新規発行廃止(令和6年12月2日)から3か月が経過し、被保険者・医療機関からの苦情等は見られないと町長が答弁。江藤議員はホームページの説明不足や医療機関に残る旧ポスターの周知不徹底を指摘し改善を求め、資格確認書はマイナ保険証を持たない方にのみ発行する国の方針を維持するとした。', '住民課', 1),
    ('ce079255-6bc8-4c1e-b11c-ed21ef65f61f', '3156aae0-4fa9-40f7-900f-04f69280de01', '短期保険証廃止後の滞納者対応', '保険証の新規発行廃止により資格書・短期保険証の概念がなくなり、特別な事情なく長期滞納がある場合は特別療養費(10割負担)に切り替えるが、機械的な運用は行わず、納付勧奨通知(約3か月に1回)や戸別訪問等を経た上での対応である旨を住民課長が説明した。', '住民課', 2),
    ('4897116b-6aba-43cc-a950-672827631463', '3156aae0-4fa9-40f7-900f-04f69280de01', '高額療養費・後期高齢者医療の支給状況', '国保の高額療養費支給額は令和4年度197,981,843円、令和5年度182,849,370円。後期高齢者医療では県内38自治体で支給漏れが発覚し、広川町でも13人・166千円余の未支給があったが速やかに支給済みとし、再発防止のためチェック体制を強化するとした。江藤議員は申請時の領収書提示の負担軽減を求めた。', '住民課', 3),
    ('53737887-7568-48f4-9811-d6f7024820ac', '3156aae0-4fa9-40f7-900f-04f69280de01', 'ふれあいタクシーの利用状況と課題', 'ふれあいタクシーの利用者数は令和5年度延べ12,849名、令和6年度は1月末時点で12,463名。令和6年9月の料金半額改定後は前年同月比約2割増、月平均約1,380名が利用。予約の取りにくさや運転手不足が新たな課題として挙げられ、既存のバス・タクシー事業者との共存を図りながら台数確保を検討するとした。', '企画課', 4),

    ('cdc53021-a19f-4b7b-b9ec-a502c1dcb341', '4d08dcd9-3349-4c66-8d52-8f9f23521a57', '人材育成基本方針の策定状況と考え方', '令和6年秋策定予定だった人材育成基本方針は国政選挙対応により遅延し最終調整段階。全職員参加のワークショップやプロジェクトチームでの協議を経て策定した点が、平成25年策定版(トップダウン型)との違いと総務課長が説明。今後は人事評価制度と連携させ実施計画を推進するとした。', '総務課', 1),
    ('34af5ea3-cb1c-4aba-b2c6-e36e9e4ead7f', '4d08dcd9-3349-4c66-8d52-8f9f23521a57', '人事交流・ウエルカムバック制度・研修', '国への研修生派遣(1名)を検討中であり、県・民間も含めた人事交流の可能性を模索していると総務課長が答弁。他自治体で導入例がある離職者再雇用の「ウエルカムバック制度」については趣旨に賛同するとしつつ、地方公務員法上の競争試験の原則との整合を今後研究するとした。', '総務課', 2),
    ('235ac7bc-8204-4756-8900-3454334f81e7', '4d08dcd9-3349-4c66-8d52-8f9f23521a57', '職場風土づくり(ロゴチャット・マンスリーレポート)', '自治体専用チャットツール「ロゴチャット」は導入当初23グループから88グループまで拡大し活用が進んでいると総務課長が説明。町長は今年度から「ワン広川ワンチーム」と題したマンスリーレポートを全職員向けに毎月発行し、一体感の醸成とフィードバックの促進を図っていると述べた。', '総務課', 3),
    ('11a965c4-ca8e-428f-b0bd-9a82e59c394b', '4d08dcd9-3349-4c66-8d52-8f9f23521a57', 'コンビニ交付の普及状況(DX)', '住民票・印鑑証明のコンビニ交付率は令和4年度15.82%、令和5年度26.63%、令和6年度1月時点27.32%まで上昇していると住民課長が答弁した。', '住民課', 4),
    ('a9811f56-ffb6-4211-b978-266c746882ca', '4d08dcd9-3349-4c66-8d52-8f9f23521a57', '窓口業務の開庁時間短縮の検討', '日曜開庁は住民係・国保年金係・納税係の3窓口に限定して継続しているが来庁者は減少傾向。町長は窓口開庁時間の短縮を働き方改革の一環として前向きに検討する考えを示しつつ、まずは書かない窓口・行かない窓口等のDX化を先行させる必要があるとした。', '総務課', 5),

    ('ebbc7975-2134-4827-badd-502ff0d5854c', '12adc70b-2d6b-46be-a139-5ab2cd4d6f4d', '校区ネット解散の経緯と地域学校協働本部への移行', '中広ネットは令和5年3月、しらかねネット(上広川校区)・せきじんネット(下広川校区)は本年3月をもって解散予定。担い手不足や地域学校協働本部への機能集約が主な理由と教育長が説明。統括推進員1名が学校運営協議会と地域学校協働本部の橋渡し役を担い、地域人材確保と運営体制強化を図る方針とした。', '教育委員会事務局生涯学習課', 1),
    ('e492929f-eefc-4875-b69e-e2444394b3d5', '12adc70b-2d6b-46be-a139-5ab2cd4d6f4d', 'まちづくり支援交付金の概要と課題', '1年間の事業実施につき300千円(補助率90%)を交付、事業年数の制約は現在緩和されている。地区担当職員による支援について第1期アンケートでは「活用できた」との回答が78%あった一方、第2期では活用が十分でないとの声も一部にあり、双方向のアクション不足が要因とされた。', '企画課', 2),
    ('d50b7890-4b6f-4a28-84df-56c8f858ee70', '12adc70b-2d6b-46be-a139-5ab2cd4d6f4d', '町民提案型協働のまちづくり事業補助金の実績と条件', '参加条件は町内に活動拠点を持つ5人以上の団体で、公益的かつ町内実施の事業が対象。行政提案型・自由提案型の2形態があり、令和2〜4年度に各6〜7事業を採択後、令和5年度は制度見直しのため休止し、令和6年度に4団体を採択して再開した。', '企画課', 3),

    ('53d4eed2-cba0-42ec-b3f1-9e68cae62b52', '5301c83b-010a-4e0e-a9f2-43e38e3cf7fb', '国道3号広川八女バイパス・県道三潴上陽線バイパスの進捗', '令和5年度に新規事業化された国道3号広川八女バイパス、県道三潴上陽線バイパスにより広域道路ネットワーク整備が進展。県道三潴上陽線の牟礼地区歩道整備(延長約260メートル)は令和7年2月末時点で用地買収の約9割完了、知徳交差点改良事業(延長約330メートル)は令和6年度新規採択され地形測量を実施中と町長が答弁した。', '建設課', 1),
    ('3a2f86e3-c706-4480-986a-659d9870f8e8', '5301c83b-010a-4e0e-a9f2-43e38e3cf7fb', '広域道路網(循環道路・久留米筑後線)整備の要望', '野田議員は久留米筑後線を軸とした広川町の循環道路構想の推進を求め、町長は市町境を越える道路整備は期成会を通じた要望が基本であり、久留米市等との意見交換の機会を捉えて要望していくと答弁した。建設課長は現在、吉常古賀線・吉里牟礼線の補助事業を優先的に整備中とした。', '建設課', 2),
    ('e8c3c959-7728-461d-b0ef-89e0d51e255a', '5301c83b-010a-4e0e-a9f2-43e38e3cf7fb', '地元施工制度の廃止と狭隘道路整備', '町道の地元施工(原材料支給による地元工事、9割補助)制度は令和7年度までとし、令和8年度から廃止予定(原材料の直接支給は継続)と建設課長が説明。狭隘道路整備事業は令和7年度に3路線を予算計上しているが、補助の措置率が55%程度と低く進捗がやや遅れているとした。', '建設課', 3),
    ('ab2cbe1a-26a8-40ee-a23d-f8be2bacc4aa', '5301c83b-010a-4e0e-a9f2-43e38e3cf7fb', '三潴上陽線歩道整備の一條区における優先順位', '三潴上陽線の歩道整備要望は当条〜一條間・牟礼地区川瀬交差点・中広川小学校〜中学校間の3か所を継続して要望しているが、一條区は現在の要望箇所に含まれていない状況。野田議員は同区が通学路安全推進会議でも危険箇所として挙がっていると指摘し、早期の要望対象化を求めた。', '建設課', 4),

    ('5444a1f6-0eca-409b-b2ec-e163c63954de', '0f5f7315-45ba-45ea-919a-eb7e7bd91dd1', '人権三法と町の人権・同和教育啓発の取組概要', '令和元年の広川町部落差別をはじめあらゆる差別の撤廃をめざす人権擁護に関する条例の一部改正、人権・同和政策推進室の設置、令和4年の広川町人権・同和教育啓発指針の改定等を通じ、人権セミナーや地域巡回講座、人権フェスタなどを実施していると教育長・生涯学習課長が説明。学校・行政職員以外の参加が2割に満たないことが課題とされた。', '教育委員会事務局生涯学習課', 1),
    ('1043759a-c3bc-44dc-a9bb-5d58af10e9d0', '0f5f7315-45ba-45ea-919a-eb7e7bd91dd1', '住民の人権意識調査結果', '平成30年実施の住民意識調査では、人権課題への関心度が福岡県民意識調査より総じて低く、職場での人権研修を「受けたことがない」「覚えていない」との回答が6割、結婚相手の家柄を問題視することを「おかしいと思うが仕方ない」等とする回答が4割超だったと生涯学習課長が説明。8年前の調査であるため、本定例会で新たな意識調査の予算を計上している。', '教育委員会事務局生涯学習課', 2),
    ('3c5409f6-a8b9-4c74-8041-2530c76bb2d0', '0f5f7315-45ba-45ea-919a-eb7e7bd91dd1', 'ハラスメント対策', '令和4年策定のハラスメント防止規定に基づき総務課に相談窓口を設置。令和7年1月にはカスタマーハラスメント対応指針を他自治体に先駆けて策定し、パワーハラスメント対応指針も最終調整中と総務課長が説明した。', '総務課', 3),
    ('d0f0e926-36f4-4227-9ffc-ad9ba016c4eb', '0f5f7315-45ba-45ea-919a-eb7e7bd91dd1', 'インターネット上の人権侵害への対応', '広川町は八女市・筑後市と連携し、掲示板や動画サイト等を対象にインターネットモニタリングを実施。人権侵害の書き込みが発見された場合はサイト管理者への削除要請や、町長自らによる八女法務局への削除要請書の提出を行っていると生涯学習課長が説明した。', '教育委員会事務局生涯学習課', 4),
    ('2fb9ac00-fc75-49a0-a1df-1ed76bd935fe', '0f5f7315-45ba-45ea-919a-eb7e7bd91dd1', '町職員・教職員の人権研修', '町職員には階層別・課題別研修や差別事象対応シミュレーション研修を実施し、本年度は差別事象対応マニュアルを作成・周知。教職員には新任者・転任者合同研修、夏季全体研修、部落問題学習研究会等を実施していると生涯学習課長が答弁した。', '教育委員会事務局生涯学習課', 5),

    ('7cbafb2f-028b-4521-ab42-3f0cab40fe59', 'b48e8fc5-03dd-4bec-b6b4-632950823d41', '上広川校区振興事業の実績と評価', '住宅取得資金利子補給は平成29年度から30件(新築24件・中古6件)、うち上広川校区への定住14件。浄化槽補助は123基(町内98件)、水道取り出し補助は71件の実績があるが、企画課長はいずれもKPI目標には届いておらず「全体的に伸びていない」と認めた。次年度から町職員によるプロジェクト会議を設置し、中広川・下広川校区も含めた移住・定住施策を総合的に検討する方針。', '企画課', 1),
    ('e769691b-4cfc-48a9-8e49-0ec66f7627cc', 'b48e8fc5-03dd-4bec-b6b4-632950823d41', '公共交通(ふれあいタクシー)の東西路線拡充', 'かつて東西を結んでいた堀川バス路線は利用者減少により廃止され、平成25年度からデマンドタクシー(現在3台)で対応。令和6年9月の料金改定以降利用者が増加しており、台数確保について令和7年度から検討するとした。国土交通省登録の時間帯・曜日の範囲内で運行する方針が企画課長より示された。', '企画課', 2),
    ('81c9d3be-443e-44ab-9dce-c8c5e931282c', 'b48e8fc5-03dd-4bec-b6b4-632950823d41', '空き家バンクの実績と改善', '空き家バンクの実績は相談106件、アドバイザー派遣43件、登録15件、成約8件にとどまる。池尻議員は宅建協会サイト「ふれんず」との違いや登録数の少なさを指摘し、企画課長は次年度から登録促進を図るとともに、相続等に問題のない古民家・土地等についても掲載を拡大する方向で検討すると答弁した。', '企画課', 3),
    ('86e4f16c-ec8b-4faf-bffd-8b517485631c', 'b48e8fc5-03dd-4bec-b6b4-632950823d41', 'スマート農業支援の方向性', '国のスマート農業補助事業は対象要件が町の営農規模に合わず、資材高騰による設備導入費の増加が課題と産業課長が説明。県のDX・スマート農業対策メニューの活用を促進しつつ、情報提供や関係団体との連携を進める方針とした。', '産業課', 4),

    ('724828c1-97aa-4be4-ab28-aaee3bdfada3', '0b18f9da-9d63-4c59-a519-182f5ee01e36', '令和5年7月豪雨災害の復旧事業進捗', '町施設の災害査定箇所は町道16・河川6・橋梁3・林道3・農道1・水路1の計30か所全てで発注済み、2月末時点で20か所完了。残る10か所のうち5か所は令和6年度末までに完了見込みで、県管理の湯之原合川線・長延川・広川(県営河川)についても大半が完了または令和6年度末完了予定と町長が答弁した。', '建設課', 1),
    ('b9e8e146-8325-4c13-befe-34fa20f49f8c', '0b18f9da-9d63-4c59-a519-182f5ee01e36', '浸水対策重点地域緊急事業と町内業者の受注割合', '県営河川広川の浸水対策重点地域緊急事業(令和6〜10年度)は本年度、調査・測量・設計と井堰統合の検討を実施中。町発注の土木工事のうち50,000千円以上は特定建設業許可業者に限られ、町内業者は4者のみのため近隣自治体業者も指名に加えていると町長が説明した。', '建設課', 2),
    ('cc6dcd6c-8b32-49b2-8cdc-6955754a29c6', '0b18f9da-9d63-4c59-a519-182f5ee01e36', '小中学校の教員配置状況', '令和6年度当初、教員定数104名に対し正規教員配置後の欠員26名、うち県常勤講師15名配置で11名不足。県非常勤講師5名・町雇用非常勤講師12名で対応し、年度途中にも県常勤講師7名・非常勤講師5名を追加配置。退職校長への声かけや久留米工業大学との連携協定を通じた人材確保にも取り組んでいると子ども課長が説明した。', '教育委員会事務局子ども課', 3),
    ('e9f258ab-f934-439c-8f12-5cd924846044', '0b18f9da-9d63-4c59-a519-182f5ee01e36', '学校施設の老朽化と法定点検', '上広川小学校、中広川小学校屋内運動場、広川中学校校舎・給食室が築40年前後を迎え老朽化が進行。学期1回以上の安全点検に加え、業者による法定点検で床・壁の剥がれや給水栓の不具合等の指摘があり、予算の範囲内で迅速に対応していると生涯学習課長が説明した。', '教育委員会事務局生涯学習課', 4),
    ('4731efc6-1eea-4c3d-a7ea-df408f1b9d8b', '0b18f9da-9d63-4c59-a519-182f5ee01e36', '産業育成(久留米絣・企業誘致)の取組', '伝統工芸である久留米絣について、令和2〜6年度のまち・ひと・しごと創生総合戦略に基づく支援に続き、次年度から高付加価値化・海外進出・人材育成を目指す新プロジェクトを計画していると産業課長が説明。工業団地は完売状態だが、数社が事業拡大を計画しており、町は候補地の情報提供等で支援する方針とした。', '産業課', 5),
    ('2a82c483-3e39-4379-a76f-8ad9417e7a8e', '0b18f9da-9d63-4c59-a519-182f5ee01e36', '職員採用の内定状況と有資格者確保', '令和6年度採用試験では一般事務・土木等の区分で11名が最終合格し全員入庁予定だが、文化財・社会福祉士区分では合格者が出ず、年度途中採用も含め対応するとした。令和7年度当初の職員数は定数増を反映し118.4人体制となる見込み。総務課長は有資格者の採用方式見直しやウエルカムバック制度の研究を進めるとした。', '総務課', 6),

    ('7ddbaa40-3970-46cd-8359-f96b0c97b1a1', '8d3656ff-64cd-4b4e-b986-13cfa3377e4b', '行政区運営の課題と町の支援策', '担い手不足や住民の参加意識低下等の課題に対し、今年度から地域コミュニティ担当者が公民館に出向き意見交換を実施。山間部の一部自治会からは当面自力運営を続けたいとの意向が示された一方、世帯数減少が進む自治会に対しては合同運営等の対応策を今後研究するとした。令和7年度は管理不全空家等の判定拡大や防災・防犯支援枠の拡大を予定していると企画課長が答弁した。', '企画課', 1),
    ('bbb43250-1236-42d0-96fe-460a48bedcd2', '8d3656ff-64cd-4b4e-b986-13cfa3377e4b', '行政区運営交付金の配分基準見直し', '行政区運営交付金は行政区割30%以内・世帯割70%以内の配分で運用されており、最大1,580千円から最小190千円程度まで交付額に大きな差が生じている。企画課長は人口減少が進む中でこの配分割合の見直しが必要と認識しているとしたが、見直し時期は未定とした。', '企画課', 2),
    ('efcc78d3-f9b9-4631-b9c8-b3d9d57e79eb', '8d3656ff-64cd-4b4e-b986-13cfa3377e4b', '行政区役員(区長・分館長・衛生班長)の委任料見直し', '区長・分館長・衛生班長の委任料は最大2,000千円台から最小270千円程度まで格差があり、業務内容が防災対応や地域活動中心へと変化している中で見直しが必要と栗原議員が指摘。分館長会への令和6年度アンケートでは格差是正を望む回答22名・現状維持10名。企画課・環境課・生涯学習課の3課が連携し検証を進めているが、算定根拠の調査に時間を要するとして、町長は見直し時期を明言しなかった。', '企画課', 3);

end $$;
